  "verses": [
    {
      "chapter": 6,
      "text_ar": "التي كان لها جمال محملة بالبضائع، وكانت تُحمل إلى أراضٍ بعيدة للفقراء، والآن تبيع شعرها من أجل الخبز!",
      "verse": 11
    },
    {
      "chapter": 6,
      "text_ar": "انظروا إليها، تلك التي كان لها سبع موائد موضوعة بثبات في بيتها، يأكل عليها كل فقير وكل غريب، والآن تبيع شعرها من أجل الخبز!",
      "verse": 12
    },
    {
      "chapter": 6,
      "text_ar": "انظروا إليها، تلك التي كان لها إجانة لغسل رجليها مصنوعة من الذهب والفضة، والآن تمشي على الأرض [وتبيع شعرها من أجل الخبز!]ً",
      "verse": 13
    },
    {
      "chapter": 6,
      "text_ar": "انظروا إليها، تلك التي كانت ثيابها مصنوعة من البسوس المنسوج بالذهب، والآن تبدل شعرها بالخبز!",
      "verse": 14
    },
    {
      "chapter": 6,
      "text_ar": "انظروا إليها، تلك التي كان لها أسرة من ذهب وفضة، والآن تبيع شعرها من أجل الخبز!",
      "verse": 15
    }
  ],
  "book_code": "TJOB"
}
